onRowSelected:
{{
  (async function() {
    // Si la ligne cliquée est un séparateur (statut ou machine), on annule
    if (Table_locations.selectedRow.isHeader || Table_locations.selectedRow.isSubHeader) {
      return;
    }

    // Historique de navigation et redirection vers le détail de la location
    await storeValue('page_precedente', '🔑 Location');
    await navigateTo('Détail Location', { id: Table_locations.selectedRow.ID });
  })()
}}

