tableData:
{{
  (function() {
    const data = get_locations.data || [];
    const result = [];
    let currentStatut = null;
    let currentMachine = null;

    data.forEach(row => {
      const machineNom = row["Matériel"] || "Machine non définie";

      // 1. En-tête principal : Changement de Statut
      if (row.Groupe_Statut !== currentStatut) {
        currentStatut = row.Groupe_Statut;
        currentMachine = null; 

        const countStatut = data.filter(r => r.Groupe_Statut === currentStatut).length;

        result.push({
          "ID": "hdr_statut_" + currentStatut,
          "N° Contrat": "",
          "Date Début": "",
          "Client": `📌 ${currentStatut.toUpperCase()} (${countStatut})`,
          "Matériel": "",
          "Statut": "",
          "Type Durée": "",
          "isHeader": true
        });
      }

      // 2. En-tête secondaire : Changement de Machine
      if (machineNom !== currentMachine) {
        currentMachine = machineNom;

        const countMachine = data.filter(r => r.Groupe_Statut === currentStatut && (r["Matériel"] || "Machine non définie") === currentMachine).length;

        result.push({
          "ID": "hdr_mach_" + currentStatut + "_" + currentMachine,
          "N° Contrat": "",
          "Date Début": "",
          "Client": `    🚜 ${currentMachine} (${countMachine})`,
          "Matériel": "",
          "Statut": "",
          "Type Durée": "",
          "isSubHeader": true
        });
      }

      // 3. Ligne de réservation classique
      result.push(row);
    });

    return result;
  })()
}}
